-- gen620: 20 zone cambiate, 41 tessere
-- c5cffb144af4c8afa72927802ab50912 (1022364) → 33979df5b436f10204137719e14a7d06 (1042138)

  on conflict (key) do update set value=excluded.value;


-- il cancello, PRIMA di scrivere
select md5(string_agg(value, '' order by key)) as md5_ricomposto,
       length(string_agg(value, '' order by key)) as len_ricomposto,
       md5(string_agg(value, '' order by key)) = '33979df5b436f10204137719e14a7d06' as combacia
from kv_store where key like 'tmp:gen620:p%';

update kv_store set value = (select string_agg(value, '' order by key) from kv_store where key like 'tmp:gen620:p%')
where key='app:jsx:src'
  and md5(value) = 'c5cffb144af4c8afa72927802ab50912'
  and (select md5(string_agg(value, '' order by key)) from kv_store where key like 'tmp:gen620:p%') = '33979df5b436f10204137719e14a7d06';

update kv_store set value = '{"len":1042138,"ver":"gen-6.20"}'
where key='app:jsx:meta'
  and (select md5(value) from kv_store where key='app:jsx:src') = '33979df5b436f10204137719e14a7d06';

delete from kv_store where key like 'tmp:gen620:p%';
